UNION ALL   SELECT 'leads', 26367, (SELECT count(*) FROM raw.leads)
UNION ALL   SELECT 'opportunities', 4200, (SELECT count(*) FROM raw.opportunities)
UNION ALL   SELECT 'opportunity_field_history', 43045, (SELECT count(*) FROM raw.opportunity_field_history)
UNION ALL   SELECT 'forecast_submissions', 1617, (SELECT count(*) FROM raw.forecast_submissions)
UNION ALL   SELECT 'arr_monthly', 9114, (SELECT count(*) FROM raw.arr_monthly)
