-- sanity: won bookings by quarter in EUR
SELECT to_char(o.close_date, 'YYYY') || '-Q' || to_char(o.close_date, 'Q') AS fiscal_quarter,
       count(*) AS deals_won, round(sum(o.amount * fx.rate_to_eur)) AS bookings_eur
FROM raw.opportunities o JOIN raw.fx_rates fx ON fx.currency = o.currency
WHERE o.is_won GROUP BY 1 ORDER BY 1;
